    // but ensure the first deposit is nonzero so it actually sets locked_ in reference and triggers behavior.
    function testFuzz_property(address actor, uint256 firstAmt, uint256 secondAmt) public {
        // admissible domain: actor is not zero address (keep wide), amounts bounded to reasonable range
        vm.assume(actor != address(0));
        // keep amounts below some large value to avoid overflow in the test environment
        firstAmt = bound(firstAmt, 1, 10 ether); // ensure firstAmt >= 1 to exercise state change
        secondAmt = bound(secondAmt, 0, 10 ether);

        // fund the actor so they can send ETH
        vm.deal(actor, firstAmt + secondAmt + 1 ether);

        // 1) actor performs first Put with firstAmt (must succeed on reference)
        vm.prank(actor);
        bool ok1;
        try c.Put{value: firstAmt}(block.timestamp) {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        // require the first call to succeed in the admissible domain; the reference always allows this for funded caller
        if (!ok1) return; // if first call failed (very unlikely given bounds), skip this fuzz case

        // 2) actor immediately calls Put again (could be same or different amount). On the reference this must succeed;
        // the mutant that never clears locked_ will make this fail for the same caller.
        vm.prank(actor);
        bool ok2;
        try c.Put{value: secondAmt}(block.timestamp) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // The universal property: after a successful Put by a caller, another Put by the same caller must succeed.
        // This holds for the reference for all admissible inputs; the mutant breaks it for some inputs (same caller).
        assertTrue(ok2);
    }
}

