import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: actor (caller) and two amounts for two sequential Put calls.
    // General rule: after a successful Put by an actor, the contract remains callable for that same actor;
    // i.e., a second Put by the same actor must not revert. The mutant that never resets locked_ can
    // make the second call revert. We fuzz actor and amounts so the fuzzer finds inputs that trigger the bug.
    function testFuzz_property(address actor, uint256 amount1, uint256 amount2) public {
        // Keep actor non-zero and amounts within a wide practical range
        vm.assume(actor != address(0));
        // bound amounts to avoid overflow in test harness and keep them reasonable for vm.deal
        amount1 = bound(amount1, 0, 10 ether);
        amount2 = bound(amount2, 0, 10 ether);

        // Fund actor so they can send the amounts
        vm.deal(actor, amount1 + amount2 + 1 ether);

        bool ok1;
        // first Put should succeed (we only care about reference contract behavior that allows further calls)
        vm.prank(actor);
        try c.Put{value: amount1}(block.timestamp) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        // If the first call reverted, the reference still must satisfy the rule vacuously only for successful first calls.
        // We restrict to the case where first call succeeded to observe the invariant about not being permanently locked.
        vm.assume(ok1);

        bool ok2;
        vm.prank(actor);
        try c.Put{value: amount2}(block.timestamp) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Single assertion: for the reference contract this is ALWAYS true (second Put does not revert after a successful first Put);
        // the mutant that omits resetting locked_ will make ok2 == false for some inputs (same actor), causing this assertion to fail.
        assertTrue(ok2);
    }
}

