import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: actor (who calls Put) and _unlockTime; value is fuzzed amount sent
    function testFuzz_property(address actor, uint256 _unlockTime, uint256 value) public {
        // keep actor non-zero to be a valid account
        vm.assume(actor != address(0));
        // bound value to a reasonable range so vm.deal can fund the actor
        value = bound(value, 0, 10 ether);

        // fund the actor so it can send value
        vm.deal(actor, value);

        // call Put as actor sending value and the fuzzed _unlockTime
        vm.prank(actor);
        c.Put{value: value}(_unlockTime);

        // The universal property: after Put, the stored unlockTime for the caller is >= block.timestamp
        // Read via public getter: Acc is public so Acc(actor).unlockTime is accessible via Acc(actor)
        (uint unlockTime, uint balance) = accOf(address(c), actor);

        assertTrue(unlockTime >= block.timestamp, "unlockTime must be >= block.timestamp after Put");
    }

    // helper to read the public struct mapping since solidity returns tuples in different order
    function accOf(address contractAddr, address who) internal view returns (uint unlockTime, uint balance) {
        // The autogenerated getter for Acc returns (uint unlockTime, uint balance) but from imported C type
        // We call through the interface by encoding the call to Acc(address)
        bytes memory payload = abi.encodeWithSignature("Acc(address)", who);
        (bool ok, bytes memory ret) = contractAddr.staticcall(payload);
        require(ok, "staticcall to Acc failed");
        (unlockTime, balance) = abi.decode(ret, (uint, uint));
    }
}

