pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz: amount > 0, and an arbitrary unlockTime; actor will be a deployed helper contract
    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        // keep amount reasonable so vm.deal works and to avoid overflow in internal bookkeeping
        amount = bound(amount, 1, 1 ether);

        // Deploy a helper that will call c via low-level call triggering fallback()
        CallerHelper helper = new CallerHelper(address(c));

        // fund the helper so it can send ETH
        vm.deal(address(helper), amount);

        // Have the helper trigger C.fallback() by sending plain ETH; fallback calls Put(0) in C
        helper.callPutWithValue{value: amount}();

        // After the call completes, in the correct contract C, Acc[helper].balance == amount
        // We assert that (the single assertion). The mutant that removed updating acc.balance breaks this
        // for some inputs (here for any amount>0), so the fuzzer will find it.
        (uint256 recordedBalance, ) = getHolder(helper);
        assertTrue(recordedBalance == amount);
    }

    // helper to read the public struct mapping return: Acc returns (unlockTime, balance) because struct fields are (uint unlockTime; uint balance)
    function getHolder(CallerHelper h) internal view returns (uint256 balance, uint256 dummy) {
        // The auto-generated getter for public mapping Acc is Acc(address) returns (uint unlockTime, uint balance).
        // We want to return balance as first value to match variable naming above; so call c.Acc(address)
        (uint256 unlockTime, uint256 bal) = c.Acc(address(h));
        return (bal, unlockTime);
    }
}

// Helper that will perform a plain value transfer to C, which triggers C.fallback() and thus calls Put(0)
contract CallerHelper {
    address payable cAddr;
    constructor(address _c) payable {
        cAddr = payable(_c);
    }
    // allow receiving ETH
    receive() external payable {}

    // call C by sending ETH with empty calldata, triggers fallback() on C
    function callPutWithValue() external payable {
        (bool s, ) = cAddr.call{value: msg.value}("");
        require(s, "call failed");
    }
}

