contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive sequence: deposit from this contract, then call Collect as the depositor.
    // Parameters:
    //  - depositAmt: amount to send in Put
    //  - collectAmt: amount to request in Collect
    //  - unlockTime: unlock time to set so Collect is allowed
    function run(uint depositAmt, uint collectAmt, uint unlockTime) public payable {
        require(address(this).balance >= depositAmt, "not enough balance");

        // deposit into c as msg.sender == this contract
        c.Put{value: depositAmt}(unlockTime);

        // ensure conditions for Collect: deposit must be >= MinSum and >= collectAmt and unlockTime passed
        // read MinSum and our recorded balance
        uint min = c.MinSum();
        uint bal = c.Acc(address(this)).balance;

        require(bal >= min, "balance below MinSum");
        require(bal >= collectAmt, "collectAmt too large");

        // move time forward is not possible here; require unlockTime to be in the past already
        require(block.timestamp > c.Acc(address(this)).unlockTime, "not unlocked");

        uint before = address(c).balance;

        // perform the withdraw (Collect) which may be reentrant in mutant
        c.Collect(collectAmt);

        uint after = address(c).balance;

        // On original contract, Collect can at most send out collectAmt from the contract balance
        // (since the depositor's own recorded balance is decremented only when the external transfer succeeds).
        assert(before - after <= collectAmt);
    }

    // allow this contract to receive Ether for making deposits
    receive() external payable {}
}

