        // Now attempt Collect as the Reverter (which will revert when receiving funds)
        bool okReverter;
        vm.prank(address(rev));
        try c.Collect(collectAmt) { okReverter = true; } catch { okReverter = false; }
        uint afterReverter = c.Acc(address(rev)).balance;

        // The universal property we assert: For the normal actor (an EOA), if the Collect call returned ok (did not revert), then afterNormal == before - collectAmt.
        // For the reverter case: The correct contract only reduces balance when the external send succeeded; thus if the external send failed (okReverter==false), the recorded balance must remain unchanged (afterReverter == rBalance).
        // We assert the latter universal property as a single assertTrue that the reference contract always satisfies: if okReverter==false then afterReverter == rBalance.

        // Compose the condition to assertTrue on the contract's observed behavior
        bool propertyHolds = true;
        if (!okReverter) {
            propertyHolds = (afterReverter == rBalance);
        } else {
            // if the reverter scenario unexpectedly succeeded in receiving funds, then we cannot reason about reduction here; keep property true
            propertyHolds = true;
        }

        assertTrue(propertyHolds);
    }
}

