pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initialDeposit, uint256 withdrawAmt) public {
        // keep values in wide, sensible ranges
        initialDeposit = bound(initialDeposit, 1 wei, 10 ether);
        withdrawAmt = bound(withdrawAmt, 1 wei, 10 ether);

        // deploy a reverter helper that will revert on receive to simulate failing external transfer
        Reverter rev = new Reverter();

        // fund the reverter so it can be the msg.sender when calling Collect (we will prank it)
        vm.deal(address(rev), 0);

        // Use the reverter as the caller: it must first deposit funds into c by calling Put via fallback
        // The contract's fallback forwards to Put(0), so send initialDeposit from rev to c
        // Give rev some ETH to deposit
        vm.deal(address(this), initialDeposit);
        // send ETH to c as if from rev: we need rev to perform the deposit, so have rev call a helper that does the deposit
        // Instead, we perform the deposit from this test account but record it under rev by writing into Acc via calling Put from rev.
        // We cannot impersonate the contract's storage, so instead deploy a depositor helper which in its constructor does Put via msg.sender semantics.
        Depositor d = new Depositor(address(c));
        // fund depositor to deposit as itself
        vm.deal(address(d), initialDeposit);
        d.deposit{value: initialDeposit}();

        // ensure depositor's recorded balance in c is initialDeposit
        // depositor used Put and therefore Acc[depositor].balance == initialDeposit
        uint256 before = c.Acc(address(d)).balance;
        assert(before == initialDeposit);

        // now attempt to Collect from depositor but route the payout to the Reverter by making depositor call Collect while msg.sender is depositor
        // The payout goes to msg.sender (depositor), but we want the transfer to fail to observe mutant behavior. To achieve that, make depositor's Collect trigger a transfer to the Reverter by using a helper Attacker that calls c.Collect and sets tx.origin or similar won't change msg.sender. Instead, we simulate failure by making depositor a contract whose fallback reverts when receiving Ether.
        // Create a depositor2 who will call Collect; deploy a depositor that previously deposited and whose receive will revert (i.e., RevertingHolder)
        RevertingHolder rh = new RevertingHolder(address(c));
        vm.deal(address(rh), initialDeposit);
        rh.deposit{value: initialDeposit}();
        uint256 before2 = c.Acc(address(rh)).balance;
        assert(before2 == initialDeposit);

        // ensure conditions: MinSum is 1 ether in contract; warp time to exceed unlockTime
        vm.warp(block.timestamp + 1 days);

        // Now have rh call Collect attempting withdrawAmt. We choose withdrawAmt bounded above; ensure withdrawAmt <= before2 to meet precondition when needed.
        withdrawAmt = bound(withdrawAmt, 1 wei, before2);

        // Call Collect from rh which will have its receive revert when the contract attempts to send it ETH
        bool ok;
        try rh.tryCollect(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After Collect completes (either ok true or false), the reference contract guarantees that Acc[rh].balance == before2 if the external transfer reverted (i.e., ok == false),
        // and Acc[rh].balance == before2 - withdrawAmt if the transfer succeeded (ok == true).
        // The general universal rule we assert: if the external transfer reverted (ok == false) then the recorded balance did not decrease.
        uint256 afterBal = c.Acc(address(rh)).balance;
        if (!ok) {
            assertTrue(afterBal == before2);
        } else {
            assertTrue(afterBal == before2 - withdrawAmt);
        }
    }
}

