// A holder contract that deposits and then attempts to Collect; its receive reverts to simulate failed payout
contract RevertingHolder {
    C c;
    constructor(address _c) { c = C(_c); }
    function deposit() external payable {
        // calling Put via fallback: send ETH directly to c so its fallback calls Put(0)
        (bool s, ) = address(c).call{value: msg.value}("");
        require(s);
    }
    function tryCollect(uint256 amt) external {
        // call Collect as this contract; when C attempts to send Ether to this contract, our receive will revert
        c.Collect(amt);
    }
    receive() external payable {
        revert("fail receive");
    }
}
